'use strict';
const MAP_FX={duration:1800,launch:230,contact:880,labelEnd:2400,minSeparation:3};
function stageMapCombat(c){
 const enemy=c.mapEnemy,start={x:state.x,y:state.y},gap=Math.hypot(start.x-enemy.x,start.y-enemy.y);
 if(gap>=MAP_FX.minSeparation&&gap<=5&&Math.abs(start.x-enemy.x)>=2){motion.facing=Math.sign(enemy.x-start.x)||1;return}
 const queue=[{...start,steps:0}],seen=new Set([idx(start.x,start.y)]),candidates=[];
 for(let i=0;i<queue.length&&i<500;i++){
  const p=queue[i],distance=Math.hypot(p.x-enemy.x,p.y-enemy.y);
  if(distance>=MAP_FX.minSeparation&&distance<=5&&!enemies.some(e=>enemyAlive(e)&&e.x===p.x&&e.y===p.y)&&!villagers.some(v=>v.x===p.x&&v.y===p.y))candidates.push({...p,score:Math.abs(distance-3.2)*3+Math.abs(p.y-enemy.y)*1.2+p.steps*.2+(Math.abs(p.x-enemy.x)<2?8:0)});
  if(p.steps>=6)continue;
  for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy;if(x<1||y<1||x>=CFG.size-1||y>=CFG.size-1||seen.has(idx(x,y))||['water','tree','mountain'].includes(tiles[idx(x,y)].type))continue;if(enemies.some(e=>enemyAlive(e)&&e.x===x&&e.y===y))continue;seen.add(idx(x,y));queue.push({x,y,steps:p.steps+1})}
 }
 candidates.sort((a,b)=>a.score-b.score);if(candidates[0]){state.x=candidates[0].x;state.y=candidates[0].y}motion.facing=Math.sign(enemy.x-state.x)||1;
}
function hideMapUnitLabels(){$('mapUnitPlayer').hidden=true;$('mapUnitEnemy').hidden=true}
function renderMapUnitLabels(c){for(const [side,fighter,id]of[['player',c.player,'mapUnitPlayer'],['enemy',c.enemy,'mapUnitEnemy']]){const node=$(id);node.hidden=false;node.innerHTML=`<span class="unit-name">${escapeText(fighter.name)}</span><div class="unit-hp-track" role="progressbar" aria-label="${escapeText(fighter.name)} health" aria-valuemin="0" aria-valuemax="${fighter.maxHP}" aria-valuenow="${fighter.hp}"><i id="${id}Fill"></i></div><small id="${id}Value">${fighter.hp}/${fighter.maxHP}</small>`}}
function mapEffectPlan(c){const plan=[];for(const side of ['player','enemy'])for(const name of c.result?.[side+'Cards']||[]){let kind;if(/Defense|Dodge|Wind|Mending/.test(name))continue;if(/Bolt|Rift|Growl|pulse/i.test(name))kind='bolt';else if(/Spark|Seal/.test(name))kind='fire';else if(/Tusk|charge/i.test(name))kind='tusk';else kind='slash';plan.push({side,kind})}return plan}
function updateMapUnitHud(c,a,b,t,elapsed){for(const [side,fighter,point,id]of[['player',c.player,a,'mapUnitPlayer'],['enemy',c.enemy,b,'mapUnitEnemy']]){const node=$(id),beforeImpact=c.phase==='reveal'&&elapsed<MAP_FX.contact&&!preferences.reduceMotion&&!reducedMotion?.matches;const hp=beforeImpact?(c.beforeHP?.[side]??fighter.hp):fighter.hp;node.style.left=Math.round(point.x)+'px';node.style.top=Math.round(point.y-t*(side==='player'?1.05:.93)-10)+'px';node.style.width=Math.max(52,Math.min(78,Math.abs(a.x-b.x)*.36))+'px';const fill=$(id+'Fill'),value=$(id+'Value');fill.style.width=Math.max(0,hp/fighter.maxHP*100)+'%';const text=hp+'/'+fighter.maxHP;if(value.textContent!==text){value.textContent=text;node.querySelector('.unit-hp-track')?.setAttribute('aria-valuenow',String(hp))}}}
function mapSpriteHitFlash(kind,x,y,t){const c=combat;if(!c?.onMap||c.phase!=='reveal'||preferences.reduceMotion||reducedMotion?.matches)return 0;const side=kind==='hero'?'player':'enemy',position=side==='player'?state:c.mapEnemy;if(side==='enemy'&&(Math.abs(x-(view.ox+(position.x+.5)*t))>2||Math.abs(y-(view.oy+(position.y+.5)*t))>2))return 0;if(!c.result?.[side].damage)return 0;const time=performance.now()-c.effectStarted-MAP_FX.contact;return time>=0&&time<140?.5*Math.sin(time/140*Math.PI):0}
function drawMapEncounter(ox,oy,t){
 const c=combat;if(!c?.onMap||atlas)return;const point=e=>({x:ox+(e.x+.5)*t,y:oy+(e.y+.5)*t}),a=point(state),b=point(c.mapEnemy),elapsed=performance.now()-(c.effectStarted??performance.now()),still=preferences.reduceMotion||reducedMotion?.matches;
 updateMapUnitHud(c,a,b,t,elapsed);
 for(const [p,color]of[[a,'#c4d59b'],[b,'#e5ad8a']]){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(p.x,p.y+t*.48,t*.4,t*.13,0,0,7);ctx.stroke()}
 if(c.phase!=='reveal'||!c.result)return;
 const report=(p,result,side)=>{const age=elapsed-MAP_FX.contact;if(!still&&(age<0||elapsed>MAP_FX.labelEnd))return;const fade=still?1:Math.min(1,(MAP_FX.labelEnd-elapsed)/450),rise=still?0:Math.min(18,Math.max(0,age)/55),y=p.y-t*.45-rise,x=p.x+(side==='player'?-1:1)*t*.85;ctx.save();ctx.globalAlpha=Math.max(0,fade);ctx.textAlign='center';ctx.font=`bold ${Math.min(18,Math.max(12,t*.16))}px Arial`;ctx.lineWidth=3;ctx.strokeStyle='#193022';ctx.fillStyle='#fff2d4';const text=result.damage?'−'+result.damage:result.blocked?'Blocked':result.dodged?'Dodged':'';ctx.strokeText(text,x,y);ctx.fillText(text,x,y);if(result.blocked&&result.damage){ctx.font='10px Arial';ctx.fillStyle='#c3e1f2';ctx.strokeText(result.blocked+' blocked',x,y+17);ctx.fillText(result.blocked+' blocked',x,y+17)}if(result.healed){ctx.font='11px Arial';ctx.fillStyle='#c6e6ad';ctx.strokeText('+'+result.healed+' HP',x,y-18);ctx.fillText('+'+result.healed+' HP',x,y-18)}ctx.restore()};
 report(a,c.result.player,'player');report(b,c.result.enemy,'enemy');if(still)return;
 const plan=mapEffectPlan(c),flight=(elapsed-MAP_FX.launch)/(MAP_FX.contact-MAP_FX.launch);
 const drawWave=(from,to,kind,lane)=>{const dx=to.x-from.x,dy=to.y-from.y,len=Math.max(1,Math.hypot(dx,dy)),ux=dx/len,uy=dy/len,begin={x:from.x+ux*t*.35,y:from.y-t*.2+uy*t*.35},end={x:to.x-ux*t*.3,y:to.y-t*.2-uy*t*.3};const u=Math.max(0,Math.min(1,flight)),bend=Math.sin(u*Math.PI)*lane,x=begin.x+(end.x-begin.x)*u-uy*bend,y=begin.y+(end.y-begin.y)*u+ux*bend,size=Math.min(25,Math.max(12,t*.21));ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(dy,dx));ctx.globalAlpha=Math.min(1,u*8,(1-u)*12);if(kind==='bolt'||kind==='fire'){const color=kind==='fire'?'#efb567':'#bdd4ff';ctx.fillStyle=kind==='fire'?'#d8784488':'#829ee688';ctx.fillRect(-size*2.2,-size*.2,size*2.2,size*.4);ctx.shadowColor=color;ctx.shadowBlur=13;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(size*.55,0);ctx.lineTo(0,-size*.4);ctx.lineTo(-size*.65,0);ctx.lineTo(0,size*.4);ctx.closePath();ctx.fill();ctx.fillStyle='#fff5df';ctx.fillRect(-2,-2,4,4)}else{ctx.fillStyle=kind==='tusk'?'#e9d6ae':'#fff0c2';ctx.strokeStyle=kind==='tusk'?'#a18153':'#caa262';ctx.lineWidth=1.5;const crescent=shift=>{ctx.beginPath();ctx.moveTo(-size*.3,-size+shift);ctx.quadraticCurveTo(size*.85,shift,-size*.3,size+shift);ctx.quadraticCurveTo(size*.15,shift,-size*.3,-size+shift);ctx.fill();ctx.stroke()};crescent(0);if(kind==='tusk'){ctx.scale(.7,.7);ctx.translate(-size*.6,size*.6);crescent(0)}}ctx.restore()};
 if(flight>=0&&flight<=1)for(const [i,effect]of plan.entries()){drawWave(effect.side==='player'?a:b,effect.side==='player'?b:a,effect.kind,(effect.side==='player'?-1:1)*(8+(i%3)*6))}
 if(elapsed>=100&&elapsed<MAP_FX.launch+170&&plan.some(e=>e.side==='player'&&e.kind==='slash')){const angle=Math.atan2(b.y-a.y,b.x-a.x),swing=Math.max(0,Math.min(1,(elapsed-100)/250));ctx.save();ctx.translate(a.x+Math.cos(angle)*t*.3,a.y-t*.2);ctx.rotate(angle-1.1+swing*1.7);ctx.strokeStyle='#223327';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.min(44,t*.52),0);ctx.stroke();ctx.strokeStyle='#ede8ce';ctx.lineWidth=2;ctx.stroke();ctx.restore()}
 const age=elapsed-MAP_FX.contact;
 for(const [p,result]of[[a,c.result.player],[b,c.result.enemy]]){
  if(result.blocked&&elapsed>130&&age<360){ctx.save();ctx.globalAlpha=age<0?.22:Math.max(0,.85-age/430);ctx.translate(p.x,p.y-t*.2);ctx.strokeStyle='#b6d9ee';ctx.lineWidth=2.5;const w=t*.42,h=t*.55;ctx.beginPath();ctx.moveTo(-w*.5,-h*.4);ctx.lineTo(0,-h*.6);ctx.lineTo(w*.5,-h*.4);ctx.lineTo(w*.45,h*.2);ctx.lineTo(0,h*.55);ctx.lineTo(-w*.45,h*.2);ctx.closePath();ctx.stroke();ctx.restore()}
  if((result.damage||result.blocked)&&age>=0&&age<300){ctx.save();ctx.globalAlpha=1-age/300;const color=result.blocked?'#bddbec':'#f1d19a';for(let i=0;i<7;i++){const angle=i*Math.PI*2/7,spread=5+age*.08;ctx.fillStyle=color;ctx.fillRect(Math.round(p.x+Math.cos(angle)*spread),Math.round(p.y-t*.2+Math.sin(angle)*spread),3,3)}ctx.restore()}
 }
}
